#include <iostream>
#include <cstring>
#include <algorithm>
using namespace std;

int h, m, s, t1, t2;
int flag[43200];

int main() {
    int a[3];

    cin >> h >> m >> s >> t1 >> t2;

    a[0] = 3600 * (h % 12) + 60 * m + s;
    a[1] = 720 * m + 12 * s;
    a[2] = 720 * s;

    t1 = 3600 * (t1 % 12);
    t2 = 3600 * (t2 % 12);

    sort(a, a + 3);
    memset(flag, 0, sizeof(flag));

    for (int i = a[0]; i < a[1]; ++i) flag[i] = 1;
    for (int i = a[1]; i < a[2]; ++i) flag[i] = 2;

    cout << (flag[t1] == flag[t2] ? "YES" : "NO");

    return 0;
}

